'use client';

import { useEffect, useState } from 'react';
import { ArrowUpRight, List, X } from '@phosphor-icons/react';
import { LiveDot } from './motion-primitives';

const LINKS = [
  { href: '/#work', label: 'Case studies' },
  { href: '/#builds', label: 'Builds' },
  { href: '/#experience', label: 'Experience' },
  { href: '/#about', label: 'About' },
];

const RESUME =
  'https://drive.google.com/file/d/1qxyGEIRskjYCb9Ry_yulhfnbb-nR_Trk/view?usp=sharing';

export default function Nav() {
  const [stuck, setStuck] = useState(false);
  const [open, setOpen] = useState(false);

  /* IntersectionObserver on a sentinel, never a scroll listener (Section 6). */
  useEffect(() => {
    const el = document.createElement('div');
    el.style.cssText = 'position:absolute;top:0;height:24px;width:1px;visibility:hidden';
    document.body.prepend(el);
    const io = new IntersectionObserver(([e]) => setStuck(!e.isIntersecting));
    io.observe(el);
    return () => {
      io.disconnect();
      el.remove();
    };
  }, []);

  return (
    <header
      className={`fixed inset-x-0 top-0 z-40 transition-colors duration-300 ${
        stuck ? 'border-b border-ink-800 bg-ink-950/80 backdrop-blur-xl' : 'border-b border-transparent'
      }`}
    >
      <div className="mx-auto flex max-w-7xl items-center justify-between gap-6 px-6 py-4 lg:px-10">
        <a href="/#top" className="flex items-center gap-2.5 text-sm font-medium tracking-tight">
          <LiveDot />
          Abhinay Tiwari
        </a>

        <nav className="hidden items-center gap-1 md:flex">
          {LINKS.map((l) => (
            <a
              key={l.href}
              href={l.href}
              className="rounded-full px-3.5 py-2 text-sm text-ink-400 transition-colors hover:bg-ink-800/60 hover:text-ink-50"
            >
              {l.label}
            </a>
          ))}
          <a
            href={RESUME}
            target="_blank"
            rel="noopener"
            className="tactile ml-2 inline-flex items-center gap-1.5 rounded-full border border-ink-700 px-4 py-2 text-sm transition-colors hover:border-ink-500 hover:bg-ink-50 hover:text-ink-950"
          >
            Resume
            <ArrowUpRight size={14} weight="bold" />
          </a>
        </nav>

        <button
          onClick={() => setOpen((v) => !v)}
          className="md:hidden"
          aria-label={open ? 'Close menu' : 'Open menu'}
          aria-expanded={open}
        >
          {open ? <X size={22} weight="regular" /> : <List size={22} weight="regular" />}
        </button>
      </div>

      {open && (
        <nav className="mx-6 mb-3 grid gap-1 rounded-2xl border border-ink-800 bg-ink-900 p-2 md:hidden">
          {LINKS.map((l) => (
            <a
              key={l.href}
              href={l.href}
              onClick={() => setOpen(false)}
              className="rounded-xl px-4 py-3 text-sm text-ink-200 hover:bg-ink-800"
            >
              {l.label}
            </a>
          ))}
          <a
            href={RESUME}
            target="_blank"
            rel="noopener"
            className="rounded-xl px-4 py-3 text-sm text-accent"
          >
            Resume
          </a>
        </nav>
      )}
    </header>
  );
}
